async updateBlueprint(blueprintId: string, options: {
  title?: string;
  description?: string;
  updateCode?: boolean;
  updateBindings?: boolean;
  screenshot?: BlueprintScreenshotUpload | null;
}): Promise<void> {
  let record = this.impl.storage.blueprints.get(blueprintId);
