function waitForPort(port: number, timeoutMs: number): Promise<void> {
  return new Promise<void>(resolve => {
    const deadline = Date.now() + timeoutMs;
    const attempt = () => {
      const socket = connect({ port, host: "127.0.0.1" });
      socket.once("connect", () => {
