    failureSite: boundString(failureSite, MAX_STRING_CHARS, mark),
    severity: options?.severity ?? "error",
    handled: options?.handled ?? false,
    exception,
    ...(correlation && { correlation }),
    ...(http && { http }),
    ...(attributes && { attributes }),
    ...(truncated ? { truncated: true } : {}),
